tool_input.command:
Start-Sleep -Seconds 2
Write-Output "=== port ==="; Get-NetTCPConnection -LocalPort 18098,18099 -State Listen -ErrorAction SilentlyContinue | Select-Object LocalPort,OwningProcess | Format-Table -AutoSize
Write-Output "=== /api/state ==="; try { (Invoke-WebRequest -Uri 'http://127.0.0.1:18098/api/state' -UseBasicParsing -TimeoutSec 5).StatusCode } catch { $_.Exception.Message }
Write-Output "=== new endpoint no-token (expect 403; 404=old code) ==="
try { (Invoke-WebRequest -Uri 'http://127.0.0.1:18098/api/registry/upsert' -Method POST -Body '{}' -ContentType 'application/json' -UseBasicParsing -TimeoutSec 5).StatusCode } catch { if ($_.Exception.Response) { [int]$_.Exception.Response.StatusCode } else { $_.Exception.Message } }

Start-Sleep -Seconds 4
Write-Output "=== listen ports ==="; netstat -ano | Select-String '18098|18099' | Select-String 'LISTENING'
Write-Output "=== task info ==="; Get-ScheduledTaskInfo -TaskName 'deploy-env-dashboard' | Select-Object LastRunTime,LastTaskResult | Format-List
foreach ($port in 18098,18099) {
  Write-Output "=== /api/state on $port ==="
  try { $r=Invoke-WebRequest -Uri "http://127.0.0.1:$port/api/state" -UseBasicParsing -TimeoutSec 5; Write-Output "HTTP $($r.StatusCode) len=$($r.Content.Length)" } catch { if ($_.Exception.Response) { Write-Output "HTTP $([int]$_.Exception.Response.StatusCode)" } else { Write-Output $_.Exception.Message } }
}
